arguments.command:
python3 -c "
from inifile import parse
text = '[server]\nurl = http://localhost:8000/?debug=1\ncolor = #ff8800\n'
r = parse(text)
print(r)
assert r['server']['url'] == 'http://localhost:8000/?debug=1', r['server']['url']
assert r['server']['color'] == '#ff8800', r['server']['color']
# edge cases
assert parse('[a]\nk = a=b=c\n') == {'a': {'k': 'a=b=c'}}
assert parse('[a]\nk = #not a comment\n') == {'a': {'k': '#not a comment'}}
assert parse('[a]\nk =\n') == {'a': {'k': ''}}
assert parse('[a]\nk =  # trailing comment line? no - value is # trailing comment line? no\n') == {'a': {'k': '# trailing comment line? no'}}
for bad in ['x = 1\n', '[a]\njust words\n', '[a]\n\n', '[a]\n= v\n']:
    try:
        parse(bad)
        raise AssertionError('should have raised: ' + repr(bad))
    except ValueError:
        pass
print('all good')
"
